DROP TABLE "public"."Activity_profile";

DROP TABLE "public"."Dietary_preferences";

DROP TABLE "public"."Recipe";

DROP TABLE "public"."Users";

DROP TABLE "public"."user_goals";

DROP TABLE "public"."user_profile";

CREATE TABLE "public"."my_recipes" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."my_recipies_id_seq") NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "recipe_id"  bigint,
  "status"     text,
  "rating"     boolean,
  CONSTRAINT "my_recipies_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."my_recipes"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."recipe" (
  "id"                 bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."Recipe_id_seq") NOT NULL,
  "created_at"         timestamp with time zone NOT NULL DEFAULT now(),
  "Name"               text,
  "Link"               text,
  "Diet type"          text[],
  "Meal Type"          character varying,
  "Symbols"            integer[]                DEFAULT '{0}'::integer[],
  "Kitchen Appliances" text[],
  "Cuisine"            text,
  "Nutrition"          real[],
  "Ingredients"        text[],
  "Time"               integer,
  CONSTRAINT "Recipe_Name_key" UNIQUE ("Name"),
  CONSTRAINT "Recipe_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."recipe"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."users_my_recipes" (
  "id"            bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "users_id"      bigint,
  "my_recipes_id" bigint,
  CONSTRAINT "users_my_recipes_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."users_my_recipes"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."users" (
  "id"                      bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."User_id_seq") NOT NULL,
  "created_at"              timestamp with time zone NOT NULL DEFAULT now(),
  "current_weight"          real,
  "height"                  real,
  "dietary_restrictions"    text[],
  "disliked_ingredients"    text[],
  "kitchen_appliances"      text[],
  "primary_goal"            text,
  "stats_preferences"       text[],
  "user_id"                 bigint,
  "username"                text,
  "display_name"            text,
  "email"                   text                     NOT NULL,
  "age"                     bigint,
  "sex"                     text,
  "preferred_weight_unit"   text,
  "secondary_goal"          text,
  "target_weight"           real,
  "goal_start_date"         date,
  "goal_updated_at"         date,
  "activity_level"          text,
  "workouts_per_week"       bigint,
  "preferred_exercise_type" text,
  "daily_step_goal"         bigint,
  "password"                text,
  "questionnare_completed"  boolean,
  CONSTRAINT "User_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."users"
  ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."my_recipes"
  ADD CONSTRAINT "my_recipies_recipe_id_fkey" FOREIGN KEY (recipe_id) REFERENCES public.recipe(id);

ALTER TABLE "public"."users_my_recipes"
  ADD CONSTRAINT "users_my_recipes_my_recipes_id_fkey" FOREIGN KEY (my_recipes_id) REFERENCES public.my_recipes(id) ON DELETE CASCADE;

ALTER TABLE "public"."users_my_recipes"
  ADD CONSTRAINT "users_my_recipes_users_id_fkey" FOREIGN KEY (users_id) REFERENCES public.users(id) ON UPDATE CASCADE ON DELETE CASCADE;

CREATE POLICY "Allow public read access" ON "public"."recipe"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

COMMENT ON COLUMN "public"."users"."email" IS 'email address used';

COMMENT ON COLUMN "public"."users"."user_id" IS 'Unique identifier for user';

COMMENT ON COLUMN "public"."users"."username" IS 'User can optionally select a username for their profile';

COMMENT ON TABLE "public"."my_recipes" IS 'contains a users saved recipes. columns include a foreign key to our main recipes database, the status in regard to the user, and the users rating';

COMMENT ON TABLE "public"."recipe" IS 'Table containing all app recipes and their corresponding information.';

COMMENT ON TABLE "public"."users" IS 'Table containing all user specific information of all app users.';

COMMENT ON TABLE "public"."users_my_recipes" IS 'joining table to allow us to access the list of foreign keys in users that link into my_recipes. best way to complete this task so when each table changes, we don''t run into any issues.';

